#!/usr/bin/env node
/**
 * gen-content-en.mjs — one-off authoring aid.
 *
 * Emits src/i18n/content.en.ts from the English reference text in
 * src/data/{landmarks,nature}.ts, so the localized content modules can never
 * silently drift from the data (mismatched slugs or missing fields).
 *
 * This is NOT part of `npm run build`; it is re-run only when a curated record
 * changes. The generated file is committed.
 */
import { build } from 'esbuild'
import { writeFileSync, mkdtempSync } from 'node:fs'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { pathToFileURL } from 'node:url'

const root = process.cwd()
const dir = mkdtempSync(path.join(tmpdir(), 'gce-content-'))
const entry = path.join(dir, 'entry.ts')

writeFileSync(
  entry,
  `export { landmarks } from ${JSON.stringify(path.join(root, 'src/data/landmarks.ts'))}\n` +
    `export { natureSites } from ${JSON.stringify(path.join(root, 'src/data/nature.ts'))}\n`
)

const outfile = path.join(dir, 'bundle.mjs')
await build({
  entryPoints: [entry],
  outfile,
  bundle: true,
  format: 'esm',
  platform: 'neutral',
  logLevel: 'error',
})

const { landmarks, natureSites } = await import(pathToFileURL(outfile).href)

/** Only copy fields that the localized modules must also provide. */
const LANDMARK_FIELDS = ['name', 'type', 'built', 'height', 'period', 'description', 'bestTime']
const NATURE_FIELDS = ['name', 'type', 'area', 'established', 'description', 'climate', 'bestTime']

function pick(record, fields) {
  const out = {}
  for (const field of fields) {
    if (typeof record[field] === 'string') out[field] = record[field]
  }
  return out
}

const landmarkCopy = {}
for (const record of landmarks) {
  landmarkCopy[record.slug] = {
    ...pick(record, LANDMARK_FIELDS),
    facts: [...record.facts],
  }
}

const natureCopy = {}
for (const record of natureSites) {
  natureCopy[record.slug] = {
    ...pick(record, NATURE_FIELDS),
    wildlife: [...record.wildlife],
    activities: [...record.activities],
    facts: [...record.facts],
  }
}

const body = `// GENERATED by scripts/dev/gen-content-en.mjs — do not hand-edit.
//
// English reference copy for curated landmark and nature records. The
// corresponding .fr and .ar modules must expose exactly the same slugs and
// fields; tests/content.test.mjs enforces that, and scripts/check-content.mjs
// fails the build if they drift.
//
// src/data/{landmarks,nature}.ts hold the structural facts (slugs, codes,
// coordinates, list membership). This module holds only user-visible prose.

export type LandmarkCopy = {
  name: string
  type: string
  built: string
  height?: string
  period: string
  description: string
  bestTime?: string
  facts: string[]
}

export type NatureCopy = {
  name: string
  type: string
  area?: string
  established?: string
  description: string
  climate: string
  bestTime: string
  wildlife: string[]
  activities: string[]
  facts: string[]
}

export type LandmarkCopyDict = Record<string, LandmarkCopy>
export type NatureCopyDict = Record<string, NatureCopy>

export const landmarksEn: LandmarkCopyDict = ${JSON.stringify(landmarkCopy, null, 2)}

export const natureEn: NatureCopyDict = ${JSON.stringify(natureCopy, null, 2)}
`

const target = path.join(root, 'src/i18n/content.en.ts')
writeFileSync(target, body)
console.log(
  `wrote src/i18n/content.en.ts — ${Object.keys(landmarkCopy).length} landmarks, ${Object.keys(natureCopy).length} nature sites`
)
